mapper.sql:
WHERE sm.facility_id = #{facilityId}
  AND sm.start_at >= #{startAt}
  AND sm.start_at <= #{endAt}
  AND sm.status = '종료'

mapper.select:
SELECT COUNT(*)
  FROM match_participant mp
  JOIN social_match sm ON sm.match_id = mp.match_id
  JOIN facility f      ON f.facility_id = sm.facility_id
                      AND f.deleted_at IS NULL
  JOIN facility_manager fm ON fm.facility_id = f.facility_id
                          AND fm.user_id = #{managerUserId}
 WHERE sm.facility_id = #{facilityId}
   AND sm.start_at >= #{startAt}
   AND sm.start_at <= #{endAt}
   AND sm.status = '종료'
   AND mp.participation_status = '확정'

mapper.sql:
FROM (
      SELECT ma.application_type,
             ma.status,
             sm.start_at,
             ROW_NUMBER() OVER (
                 PARTITION BY ma.match_id, ma.applicant_user_id
                 ORDER BY ma.created_at DESC, ma.application_id DESC
             ) AS latest_rank
        FROM match_application ma
        JOIN social_match sm ON sm.match_id = ma.match_id
        JOIN facility f      ON f.facility_id = sm.facility_id
                            AND f.deleted_at IS NULL
        JOIN facility_manager fm ON fm.facility_id = f.facility_id
                                AND fm.user_id = #{managerUserId}
       WHERE sm.facility_id = #{facilityId}
         AND sm.start_at >= #{startAt}
         AND sm.start_at <= #{endAt}
         AND sm.status = '종료'
     ) latest
